import{_ as a,o as i,c as t,a7 as n}from"./chunks/framework.DUCm5Bu5.js";const p=JSON.parse('{"title":"Changelog","description":"Dated changes for the public release series.","frontmatter":{"title":"Changelog","description":"Dated changes for the public release series.","updated":"2026-10-18T00:00:00.000Z"},"headers":[],"relativePath":"en/project/changelog.md","filePath":"en/project/changelog.md"}'),o={name:"en/project/changelog.md"};function r(l,e,s,d,c,u){return i(),t("div",null,[...e[0]||(e[0]=[n('<h2 id="unreleased-—-2026-10-18-utc-08-00" tabindex="-1">Unreleased — 2026-10-18 (UTC+08:00) <a class="header-anchor" href="#unreleased-—-2026-10-18-utc-08-00" aria-label="Permalink to &quot;Unreleased — 2026-10-18 (UTC+08:00)&quot;">​</a></h2><ul><li>Expanded the four-language guides with verified steps: installation and quickstart distinguish source builds from packages that are not published yet; configuration documents profile composition, environment variables, ports, persistence and client data; deployment covers Docker Compose, backups, upgrades and rollback; troubleshooting follows symptom → check → cause → fix.</li><li>Added a practical first-plugin walkthrough to the plugins guide and language quick starts, capability negotiation and conformance testing to the SDK protocol reference.</li><li>Rewrote the project README in English and Chinese with requirements, Windows and Linux quick starts, Docker Compose, the client-data boundary and documentation entry points.</li><li>Corrected statements that did not match the current code. Unpublished download and installer endpoints remain marked as coming soon. Documentation only: runtime behaviour is unchanged.</li><li>Added a Launcher guide in all four site languages: the companion Fantasy Tale Launcher&#39;s client builds, session and login-ticket model, hook plugins, distribution boundary, and the server&#39;s <code>launcher.http</code> API for operators, including the HTTP 426 version gate, JSON compatibility rules and the ticket security boundary. Documentation only.</li></ul><h2 id="unreleased-—-2026-10-16-utc-08-00" tabindex="-1">Unreleased — 2026-10-16 (UTC+08:00) <a class="header-anchor" href="#unreleased-—-2026-10-16-utc-08-00" aria-label="Permalink to &quot;Unreleased — 2026-10-16 (UTC+08:00)&quot;">​</a></h2><ul><li>Added declared SDK events on the native event bus, including serial/parallel notifications, waterfall interception and bail decisions across languages.</li><li>Preserved event continuation ownership and Rust callback cleanup; fixed a race that could hide a recorded activation timeout during shutdown.</li><li>Added SDK service providers, decorator chains and ordered service collections across Python, TypeScript, Go and Rust, including Go/Rust WebAssembly.</li><li>Preserved ownership of admitted work through cancellation and timeouts, and fixed startup selection after new definitions are published.</li><li>Preserved SDK cleanup after a row timeout and released retired activation contexts while their shared process remains alive.</li><li>Updated plugin and SDK guides with registration examples, lifetime rules and explicit remaining native-parity limits.</li></ul><h2 id="unreleased-—-2026-10-15-utc-08-00" tabindex="-1">Unreleased — 2026-10-15 (UTC+08:00) <a class="header-anchor" href="#unreleased-—-2026-10-15-utc-08-00" aria-label="Permalink to &quot;Unreleased — 2026-10-15 (UTC+08:00)&quot;">​</a></h2><ul><li>Prepared a new public documentation set and a Vue 3 documentation site in four languages.</li><li>Added Windows x64/ARM64 download entries and Linux installer/Docker choices; download endpoints remain coming soon.</li><li>Corrected private-file exclusion rules and removed internal tooling from the public source index.</li><li>Made public validation retain self-contained Equipment and Shop tests while explicitly excluding local-data cases.</li><li>Preserved existing bootstrap defaults and made missing local catalog data fail instead of reporting a test pass.</li></ul><p>This is preparation for the first public release, not an announcement that packages or a documentation site have been published. Detailed changes are maintained in the repository&#39;s root changelogs.</p>',7)])])}const g=a(o,[["render",r]]);export{p as __pageData,g as default};
